# Actual week question

from datetime import date, timedelta

# Reference Sunday
start_date = date(2025, 9, 21)

# Today
today = date.today()

# If before the start date → always 1
if today < start_date:
    actual_week = 1
else:
    # Number of full weeks since start_date (Sundays)
    weeks_since_start = (today - start_date).days // 7
    actual_week = weeks_since_start + 1
