    def get_user_choice(options, multiple_choice=False):
        while True:
            for i, option in enumerate(options):
                print(f"{i+1}. {option}")
            choice = input("Enter your choice (separated by commas for multiple options): ")
            if choice.strip() == "":
                return 0  # Return 0 if choice is empty
            choice_list = choice.split(",")
            choice_list = [int(c.strip()) for c in choice_list if c.strip().isdigit()]
            if multiple_choice:
                if all(1 <= c <= len(options) for c in choice_list):
                    return choice_list
            else:
                if len(choice_list) == 1 and 1 <= choice_list[0] <= len(options):
                    return choice_list[0]
            print("Invalid choice. Please try again.")
    
    
